import{bQ as e,aL as t,u as a,G as n}from"./chunks/framework.DaEK0KQB.js";const h=JSON.parse('{"title":"nrm详解","description":"","frontmatter":{"title":"nrm详解","date":"2024-06-04T09:40:27.000Z","permalink":"/pages/c326a4/","categories":["github","技巧"],"tags":[null]},"headers":[],"relativePath":"github/技巧/05.nrm详解.md","filePath":"github/技巧/05.nrm详解.md","lastUpdated":1785225860000}'),o={name:"github/技巧/05.nrm详解.md"};function p(s,r,m,i,d,c){return t(),a("div",null,[...r[0]||(r[0]=[n('<h1 id="nrm详解" tabindex="-1">nrm详解 <a class="header-anchor" href="#nrm详解" aria-label="Permalink to &quot;nrm详解&quot;">​</a></h1><h2 id="_1-什么是nrm" tabindex="-1">1.什么是nrm <a class="header-anchor" href="#_1-什么是nrm" aria-label="Permalink to &quot;1.什么是nrm&quot;">​</a></h2><p>nrm 是一个 npm 源管理器，允许你快速地在 npm源间切换。</p><p>什么意思呢，npm默认情况下是使用npm官方源（使用npm config ls命令可以查看），在国内用这个源肯定是不靠谱的，一般我们都会用淘宝npm源：<a href="https://registry.npm.taobao.org/%EF%BC%8C%E4%BF%AE%E6%94%B9%E6%BA%90%E7%9A%84%E6%96%B9%E5%BC%8F%E4%B9%9F%E5%BE%88%E7%AE%80%E5%8D%95%EF%BC%8C%E5%9C%A8%E7%BB%88%E7%AB%AF%E8%BE%93%E5%85%A5%EF%BC%9A" target="_blank" rel="noreferrer">https://registry.npm.taobao.org/，修改源的方式也很简单，在终端输入：</a></p><p><code>npm set registry https://registry.npm.taobao.org/</code></p><p>再npm config ls查看，已经切换成功。</p><p>那么，问题来了，如果哪天你又跑去国外了，淘宝源肯定是用不了的，又要切换回官网源，或者哪天你们公司有自己的私有npm源了，又需要切换成公司的源，这样岂不很麻烦？于是有了nrm。</p><h2 id="_2-nrm安装" tabindex="-1">2.nrm安装 <a class="header-anchor" href="#_2-nrm安装" aria-label="Permalink to &quot;2.nrm安装&quot;">​</a></h2><p><code>npm install -g nrm</code></p><h2 id="_3-nrm使用" tabindex="-1">3.nrm使用 <a class="header-anchor" href="#_3-nrm使用" aria-label="Permalink to &quot;3.nrm使用&quot;">​</a></h2><p><code>nrm ls</code></p><p><strong>星号代表当前使用源</strong></p><p><code>nrm ls</code><img src="https://cdn.jsdelivr.net/gh/akcshen/chartBed@master/assets/img/202406040942495.png" alt="image-20240604094251959"></p><p><strong>查看当前源</strong></p><p><code>nrm current</code></p><p><img src="https://cdn.jsdelivr.net/gh/akcshen/chartBed@master/assets/img/202406040943863.png" alt="image-20240604094357836"></p><p><strong>切换源</strong></p><p><code>nrm use &lt;registry&gt;</code></p><p>registry为源名;比如：切换为taobao源</p><p><code>nrm use taobao</code></p><h2 id="_4-添加源" tabindex="-1">4.添加源 <a class="header-anchor" href="#_4-添加源" aria-label="Permalink to &quot;4.添加源&quot;">​</a></h2><p><code>nrm add &lt;registry&gt; &lt;url&gt;</code></p><p>registry为源名，url为源地址。</p><p>比如：添加一个公司私有的npm源，源地址为：<a href="http://192.168.22.11:8888/repository/npm-public/%EF%BC%8C%E6%BA%90%E5%90%8D%E4%B8%BAcpm%EF%BC%88%E9%9A%8F%E6%84%8F%E5%8F%96%EF%BC%89" target="_blank" rel="noreferrer">http://192.168.22.11:8888/repository/npm-public/，源名为cpm（随意取）</a></p><p><code>nrm add cpm http://192.168.22.11:8888/repository/npm-public/</code></p><h2 id="_5-删除源" tabindex="-1">5.删除源 <a class="header-anchor" href="#_5-删除源" aria-label="Permalink to &quot;5.删除源&quot;">​</a></h2><p><code>nrm del &lt;registry&gt;</code></p><h2 id="_6-测试源速度" tabindex="-1">6.测试源速度 <a class="header-anchor" href="#_6-测试源速度" aria-label="Permalink to &quot;6.测试源速度&quot;">​</a></h2><p><code>nrm test &lt;registry&gt;</code></p>',29)])])}const g=e(o,[["render",p]]);export{h as __pageData,g as default};
